//! Bindings generated from the Vault ABI (`abi/Vault.json`, exported from `contracts/`).
#![allow(clippy::too_many_arguments)] // generated by sol! for the Vault constructor and events
use alloy::sol;

sol!(
    #[allow(missing_docs)]
    #[derive(Debug)]
    #[sol(rpc)]
    Vault,
    "abi/Vault.json"
);

/// Human-readable explanation of a revert, decoded from the vault's custom errors.
pub fn describe_revert(data: &[u8]) -> Option<String> {
    use Vault::VaultErrors as E;
    use alloy::sol_types::SolInterface;
    let err = E::abi_decode(data).ok()?;
    Some(match err {
        E::ConditionNotMet(e) => format!("condition not met for order {}", e.id),
        E::OrderInactive(e) => format!("order {} is inactive", e.id),
        E::InsufficientBalance(e) => {
            format!(
                "insufficient balance of {}: need {}, have {}",
                e.token, e.needed, e.available
            )
        }
        E::StalePrice(e) => format!("stale oracle price for {}", e.token),
        E::InvalidPrice(e) => format!("invalid oracle price for {}", e.token),
        E::SlippageExceeded(e) => format!(
            "slippage exceeded: received {}, minimum {}",
            e.received, e.minimum
        ),
        E::NotExecutor(_) => "this wallet is not the vault keeper".into(),
        E::EnforcedPause(_) => "vault is paused".into(),
        other => format!("{other:?}"),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloy::{
        primitives::{Address, U256},
        sol_types::SolError,
    };

    #[test]
    fn decodes_custom_errors() {
        let data = Vault::ConditionNotMet { id: U256::from(3) }.abi_encode();
        assert_eq!(
            describe_revert(&data).unwrap(),
            "condition not met for order 3"
        );

        let data = Vault::SlippageExceeded {
            received: U256::from(90),
            minimum: U256::from(99),
        }
        .abi_encode();
        assert_eq!(
            describe_revert(&data).unwrap(),
            "slippage exceeded: received 90, minimum 99"
        );

        let data = Vault::NotExecutor {}.abi_encode();
        assert_eq!(
            describe_revert(&data).unwrap(),
            "this wallet is not the vault keeper"
        );

        let data = Vault::InsufficientBalance {
            token: Address::ZERO,
            needed: U256::from(2),
            available: U256::from(1),
        }
        .abi_encode();
        assert!(
            describe_revert(&data)
                .unwrap()
                .starts_with("insufficient balance")
        );
    }

    #[test]
    fn unknown_data_is_not_decoded() {
        assert!(describe_revert(&[0xde, 0xad, 0xbe, 0xef]).is_none());
        assert!(describe_revert(&[]).is_none());
    }
}
